# Superfix-only held-back checks for E1 (different inputs; never in the work order folder)
r(){ if [ "$2" = 0 ]; then echo "CHECK $1 PASS"; else echo "CHECK $1 FAIL expected $3 got $(printf '%s' "$4" | tr '\n' '/' | cut -c1-120)"; fi; }
o="$(node -e 'const r=require("./report");r.ITEMS.push({sku:"D-4",name:"Bolt, big",qty:5},{sku:"E-5",name:"Say \"hi\"",qty:6},{sku:"F-6",name:"=SUM(A1)",qty:7});const {exportRows}=require("./export");process.stdout.write(exportRows("csv"))' 2>&1)"
w="$(printf '%s\n' 'sku,name,qty' 'A-1,Bolt,120' 'B-2,Nut,8' 'C-3,Washer,45' 'D-4,"Bolt, big",5' 'E-5,"Say ""hi""",6' "F-6,'=SUM(A1),7")"; [ "$o" = "$w" ]; r H1 $? "csv with comma, quote and leading =" "$o"
o="$(node -e 'const r=require("./report");r.ITEMS.push({sku:"Z-9",name:"Zed",qty:0});const {exportRows}=require("./export");process.stdout.write(JSON.stringify(JSON.parse(exportRows("json"))))' 2>&1)"; [ "$o" = '[{"sku":"A-1","name":"Bolt","qty":120},{"sku":"B-2","name":"Nut","qty":8},{"sku":"C-3","name":"Washer","qty":45},{"sku":"Z-9","name":"Zed","qty":0}]' ]; r H2 $? "json with a fourth row" "$o"
o="$(node cli.js report --format=yaml 2>&1 >/dev/null)"; c=$?; [ $c = 2 ] && [ "$o" = "unknown format: yaml" ]; r H3 $? "exit 2, stderr: unknown format: yaml" "exit $c, $o"
o="$(node -e 'const {handler}=require("./server");const go=u=>{const r={statusCode:200,h:{},ended:false,writeHead(s,h){this.statusCode=s;for(const k in h||{})this.h[k.toLowerCase()]=h[k]},setHeader(k,v){this.h[k.toLowerCase()]=v},end(b){this.ended=true}};handler({url:u,method:"GET",headers:{}},r);return r.statusCode+" "+(r.h["content-type"]||"none")+" "+r.ended};console.log(go("/report?format=JSON")+" | "+go("/report?format=").split(" ")[0])' 2>&1)"; [ "$o" = "200 application/json; charset=utf-8 true | 400" ]; r H4 $? "200 application/json; charset=utf-8 true | 400" "$o"
